<?php
declare(strict_types=1);
namespace DigiForgePrintifyConnector\Preparation;
use DigiForge\Connector\Printify\ShopBinding;
final class ReviewCoordinator {
 public function __construct(private ?OperationsCoreInterface $core=null){}
 public static function discover():self{try{$class='DigiForge\\Connector\\Printify\\MutationBridge';if(!class_exists($class)||!method_exists($class,'connect'))return new self();$p=$class::connect('1.0.0');return new self($p instanceof OperationsCoreInterface?$p:null);}catch(\Throwable){return new self();}}
 private function authorized(ShopBinding $s,int $actor,string $action):bool {
  try{if($actor<1||$s->expiresAt<=time()||$this->core===null||$this->core->version()!=='1.0.0'||$this->core->workflowVersion()!=='1.0.0'||$this->core->operationsVersion()!=='1.0.0')return false;$a=$this->core->authorizeWorkflow($s,$actor,$action);if(is_wp_error($a))return false;$expected=['scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'action'=>$action,'authorization_revision'=>$s->revision,'local_evidence_authorized'=>true,'external_writes_denied'=>true];if(array_diff(array_keys($a),array_merge(array_keys($expected),['expires_at'])))return false;foreach($expected as $k=>$v)if(($a[$k]??null)!==$v)return false;return is_int($a['expires_at']??null)&&$a['expires_at']>time();}catch(\Throwable){return false;}
 }
 public function queue(ShopBinding $s,int $actor):array|\WP_Error {
  if(!$this->authorized($s,$actor,'inspect_reviews'))return self::error();
  try{$r=$this->core->reviewQueue($s,$actor,20);if(is_wp_error($r)||!self::keys($r,['schema','scope_fingerprint','actor_id','checkpoint_epoch','items','read_only','external_execution_authorized','evidence_hash'])||$r['schema']!=='DF_REVIEW_QUEUE_1'||$r['scope_fingerprint']!==$s->fingerprint()||$r['actor_id']!==$actor||$r['read_only']!==true||$r['external_execution_authorized']!==false||!is_array($r['items'])||!array_is_list($r['items'])||count($r['items'])>20)return self::error();ReviewContract::digest($r['checkpoint_epoch']);$hash=$r['evidence_hash'];unset($r['evidence_hash']);if(!is_string($hash)||!hash_equals(MutationIntent::hash($r),$hash))return self::error();$seen=[];foreach($r['items']as $item){ReviewContract::item($item,$s->fingerprint(),$s->revision);if(isset($seen[$item['subject_hash']]))return self::error();$seen[$item['subject_hash']]=true;}if(!$this->authorized($s,$actor,'inspect_reviews'))return self::error();return $r+['evidence_hash'=>$hash,'retry_permitted'=>false];}catch(\Throwable){return self::error();}
 }
 public function decide(ShopBinding $s,int $actor,array $item,string $decision,string $reason):array|\WP_Error {
  if(!$this->authorized($s,$actor,'record_review')||!in_array($reason,['EVIDENCE_CHECKED','PROOF_MISSING','CORRECTION_REQUIRED','UNCERTAINTY_RETAINED'],true))return self::error();
  try{ReviewContract::item($item,$s->fingerprint(),$s->revision);$q=$this->queue($s,$actor);if(is_wp_error($q)||$item['recovery_epoch']!==$q['checkpoint_epoch'])return self::error();$found=false;foreach($q['items']as $current)if(MutationIntent::hash($current)===MutationIntent::hash($item))$found=true;if(!$found)return self::error();$next=ReviewContract::transition($item,$decision);
   $request=['schema'=>'DF_LOCAL_REVIEW_DECISION_1','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'item'=>$item,'decision'=>$decision,'reason'=>$reason,'next_review_state'=>$next,'external_execution_authorized'=>false];$request['request_hash']=MutationIntent::hash($request);$r=$this->core->decideReview($request);if(is_wp_error($r)||!self::keys($r,['schema','request_hash','scope_fingerprint','actor_id','subject_hash','operation_state','review_state','review_revision','recovery_epoch','receipt_hash','external_execution_authorized']))return self::error();
   foreach(['schema'=>'DF_LOCAL_REVIEW_RECEIPT_1','request_hash'=>$request['request_hash'],'scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'subject_hash'=>$item['subject_hash'],'operation_state'=>$item['operation_state'],'review_state'=>$next,'review_revision'=>$item['review_revision']+1,'recovery_epoch'=>$q['checkpoint_epoch'],'external_execution_authorized'=>false]as $k=>$v)if($r[$k]!==$v)return self::error();$hash=$r['receipt_hash'];unset($r['receipt_hash']);if(!is_string($hash)||!hash_equals(MutationIntent::hash($r),$hash)||!$this->authorized($s,$actor,'record_review'))return self::error();return $r+['receipt_hash'=>$hash,'retry_permitted'=>false];
  }catch(\Throwable){return self::error();}
 }
 public function observeFulfillment(ShopBinding $s,int $actor,ShipmentReadModel $model):array|\WP_Error {
  if(!$this->authorized($s,$actor,'record_fulfillment'))return self::error();$e=$model->jsonSerialize();if($e['scope_fingerprint']!==$s->fingerprint())return self::error();
  try{$q=['schema'=>'DF_FULFILLMENT_INTAKE_1','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'evidence'=>$e];$r=$this->core->recordFulfillment($q);if(is_wp_error($r)||!self::keys($r,['schema','scope_fingerprint','actor_id','order_identity','content_hash','order_version','disposition','recovery_epoch','checkpoint_epoch','receipt_hash','external_execution_authorized']))return self::error();foreach(['schema'=>'DF_FULFILLMENT_RECEIPT_1','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>$actor,'order_identity'=>$e['order_identity'],'content_hash'=>$e['content_hash'],'order_version'=>$e['order_version'],'external_execution_authorized'=>false]as $k=>$v)if($r[$k]!==$v)return self::error();ReviewContract::digest($r['recovery_epoch']);if($r['checkpoint_epoch']!==$r['recovery_epoch']||!in_array($r['disposition'],['RECORDED','DUPLICATE','CONFLICT','OUT_OF_ORDER'],true))return self::error();$hash=$r['receipt_hash'];unset($r['receipt_hash']);if(!is_string($hash)||!hash_equals(MutationIntent::hash($r),$hash)||!$this->authorized($s,$actor,'record_fulfillment'))return self::error();return ['disposition'=>$r['disposition'],'order_identity'=>$e['order_identity'],'receipt_hash'=>$hash,'manual_review_required'=>true,'retry_permitted'=>false,'external_execution_authorized'=>false];}catch(\Throwable){return self::error();}
 }
 public function fulfillment(ShopBinding $s,int $actor,string $identity,int $expectedVersion):ShipmentReadModel|\WP_Error {
  try{ReviewContract::digest($identity);if($expectedVersion<1||!$this->authorized($s,$actor,'inspect_fulfillment'))return self::error();$m=$this->core->inspectFulfillment($s,$actor,$identity);if(!$m instanceof ShipmentReadModel)return self::error();$d=$m->jsonSerialize();if($d['scope_fingerprint']!==$s->fingerprint()||$d['order_identity']!==$identity||$d['order_version']!==$expectedVersion||!$this->authorized($s,$actor,'inspect_fulfillment'))return self::error();return $m;}catch(\Throwable){return self::error();}
 }
 public function export(ShopBinding $s,int $actor):string|\WP_Error{$q=$this->queue($s,$actor);if(is_wp_error($q))return $q;$q['export_hash']=MutationIntent::hash($q);return json_encode($q,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT);}
 private static function keys(array $r,array $k):bool{return !array_diff(array_keys($r),$k)&&!array_diff($k,array_keys($r));}
 private static function error():\WP_Error{return new \WP_Error('printify_local_review_denied','Current scoped core review/journal and exact versions required.',['retry_permitted'=>false,'external_execution_authorized'=>false]);}
}
